"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

// Frosted Glass Slider — empty glass track; the Indicator fill lights up with the
// same glass material as the primary Button. Thumb is a glossy specular orb.

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track data-slot="slider-track" className="relative h-2 w-full grow overflow-hidden rounded-full backdrop-blur-[var(--fg-blur)] backdrop-saturate-150 bg-[var(--fg-fill)] shadow-[inset_0_0.0625rem_0_-0.0313rem_oklch(1_0_0/0.3)]">
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full bg-[var(--fg-fill-hover)] shadow-[var(--fg-shadow)]" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb data-slot="slider-thumb" key={index} className="block h-5 w-5 rounded-full bg-[radial-gradient(circle_at_35%_30%,oklch(1_0_0),oklch(1_0_0/0.85)_55%,oklch(0.9_0.02_285/0.7))] shadow-[0_0_0.625rem_oklch(1_0_0/0.3),0_0.0625rem_0.1875rem_oklch(0_0_0/0.35)] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-0 data-disabled:pointer-events-none data-disabled:opacity-50 hover:scale-110" />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
